import React, { useEffect, useState } from "react";

import api from "../services/api";

const BookingForm = ({
  blocks,
  formData,
  onChange,
  onSubmit,
  onAvailabilityCheck,
  loading
}) => {
  const [resources, setResources] = useState([]);
  const [resourceLoading, setResourceLoading] = useState(false);
  const [resourceError, setResourceError] = useState("");

  useEffect(() => {
    let isActive = true;

    const fetchResources = async () => {
      if (!formData.blockId) {
        setResources([]);
        setResourceError("");
        setResourceLoading(false);
        return;
      }

      setResourceLoading(true);
      setResourceError("");

      try {
        const response = await api.get(`/blocks/${formData.blockId}/resources`);
        if (isActive) {
          setResources(response.data);
        }
      } catch (error) {
        if (isActive) {
          setResources([]);
          setResourceError(error.response?.data?.detail || "Could not load resources.");
        }
      } finally {
        if (isActive) {
          setResourceLoading(false);
        }
      }
    };

    fetchResources();

    return () => {
      isActive = false;
    };
  }, [formData.blockId]);

  return (
    <div className="panel-card">
      <div className="panel-header">
        <div>
          <h3>Create Booking</h3>
          <p>Choose a block, resource, date, and time slot.</p>
        </div>
      </div>

      <form className="grid-form" onSubmit={onSubmit}>
        <label>
          <span>Block</span>
          <select name="blockId" value={formData.blockId} onChange={onChange} required>
            <option value="">Select block</option>
            {blocks.map((block) => (
              <option key={block.id} value={block.id}>
                Block {block.name}
              </option>
            ))}
          </select>
        </label>

        <label>
          <span>Resource</span>
          <select
            name="resourceId"
            value={formData.resourceId}
            onChange={onChange}
            required
            disabled={!formData.blockId || resourceLoading}
          >
            <option value="">Select resource</option>
            {resources.map((resource) => (
              <option key={resource.id} value={resource.id}>
                {resource.name}
              </option>
            ))}
          </select>
          {resourceLoading ? <small className="field-note">Loading resources...</small> : null}
          {!resourceLoading && formData.blockId && resources.length === 0 && !resourceError ? (
            <small className="field-note">No resources found for this block.</small>
          ) : null}
          {resourceError ? <small className="field-note error-text">{resourceError}</small> : null}
        </label>

        <label>
          <span>Date</span>
          <input type="date" name="bookingDate" value={formData.bookingDate} onChange={onChange} required />
        </label>

        <label>
          <span>Start time</span>
          <input type="time" name="startTime" value={formData.startTime} onChange={onChange} required />
        </label>

        <label>
          <span>End time</span>
          <input type="time" name="endTime" value={formData.endTime} onChange={onChange} required />
        </label>

        <label className="full-width">
          <span>Purpose</span>
          <textarea
            name="purpose"
            value={formData.purpose}
            onChange={onChange}
            rows="4"
            placeholder="Add purpose for this booking"
          />
        </label>

        <div className="form-actions full-width">
          <button type="button" className="secondary-button" onClick={onAvailabilityCheck}>
            Check Availability
          </button>
          <button type="submit" className="primary-button" disabled={loading}>
            {loading ? "Submitting..." : "Create Booking"}
          </button>
        </div>
      </form>
    </div>
  );
};

export default BookingForm;
